    # bar anchor & direction: horizontal -> vertical inward; vertical -> horizontal inward
    for cc in bars:
        ys={y for y,x in cc}; xs={x for y,x in cc}
        if len(ys)==1:  # horizontal
            r=list(ys)[0]
            # anchor: leftmost
            (ar,ac)=min(cc,key=lambda p:p[1])
            d=-1 if r==0 else 1  # into grid
            while True:
                cr=ar+d
                if 0<=cr<H: break
                cr+=d
            # move one step inward
            nr=ar+d
            c=ac
            while 0<=nr<H:
                if g[nr][c]!=bg and g[nr][c]!=mc: break
                if out[nr][c]==bg:
                    fill_cells([(nr,c)],fill)
                nr+=d
        else:  # vertical
            cs=list(xs)[0]
            (ar,ac)=min(cc,key=lambda p:p[0])
            d=1 if ar==H-1 else -1
            nc=ac+d
            r=ar
            while 0<=nc<W:
                if g[r][nc]!=bg and g[r][nc]!=mc: break
                if out[r][nc]==bg:
                    fill_cells([(r,nc)],fill)
                nc+=d
    # markers: emit ray toward the bar sharing row or column, filling gap; marker->4
    for (mr,mc) in singles:
        out[mr][mc]=4
        # horizontal bar in same row
        hb=[cc for cc in bars if len({y for y,x in cc})==1 and mr in {y for y,x in cc}]
        vb=[cc for cc in bars if len({x for y,x in cc})==1 and mc in {x for y,x in cc}]
        if hb:
            # ray toward nearest bar cell in that row
            best=min(hb,key=lambda cc:min(abs(y-mr) for y,x in cc))
            xs_={x for y,x in best}
            lo,hi=min(xs_),max(xs_)
            for c in range(min(mr,lo)+ (0 if mr<lo else 1), max(mr,hi)- (0 if mr>hi else -1)):
                if out[mr][c]==bg: fill_cells([(mr,c)],fill)
        if vb:
            bs={y for y,x in vb}
            lo,hi=min(bs),max(bs)
            for r in range(min(mr,lo)+(0 if mr<lo else 1), max(mr,hi)-(0 if mr>hi else -1)):
                if out[r][mc]==bg: fill_cells([(r,mc)],fill)
    return out

