            for c in range(min(mc,lo),max(mc,hi)+1):
                if g[mr][c]!=v: out[mr][c]=mv
        else:
            lo,hi=min(rs),max(rs)
            for r in range(min(mr,lo),max(mr,hi)+1):
                if g[r][mc]!=v: out[r][mc]=mv
